  ],
  "email": {
    "subject": {
      "text": "The email address on your site sits on a domain registration that runs out",
      "cites": ["f1"]
    },
    "body": [
      {
        "text": "The contact email printed on your official site sits on a domain you use, and that registration runs out. From that day, every enquiry sent to it bounces.",
        "cites": ["f1"]
      },
      {
        "text": "Your record is otherwise solid: an independent credit bureau matches your registration number, and your map rating is strong.",
        "cites": ["f4", "f6"]
      },
      {
        "text": "But none of your newest map reviews carries a reply, and your contractor grade differs between your site and a public directory — the kind of gap a tender panel notices.",
        "cites": ["f3", "c7"]
      }
    ]
  },
  "titles": [
    { "id": "f1", "text": "Your official contact email sits on a domain registration that runs out, so enquiries will bounce." },
    { "id": "f2", "text": "Your company profile's phone field holds something nobody can dial, so recruiters and buyers move on." },
    { "id": "f3", "text": "None of your newest reviews carries a reply from you, so a homeowner reads your silence as indifference." },
    { "id": "f7", "text": "A file that tells search engines what they may index is reported invalid, so your pages may stay unseen." },
    { "id": "f8", "text": "Your pages carry no contact or privacy link, so a customer with a complaint, or a bank checking you, stops." },
    { "id": "c1", "text": "Two different main phone numbers are in public use, so callers reach different lines with no idea which is sales." },
    { "id": "c2", "text": "Your two websites print different contact emails, so enquiries split across two inboxes." },
    { "id": "c3", "text": "Your head office address is published four ways, so a courier or auditor can be sent to the wrong door." },
    { "id": "c4", "text": "Your two sites list different branches, so customers cannot tell which offices are current." },
    { "id": "c5", "text": "Three different staff counts are in public, so a tender panel judging your capacity gets three answers." },
    { "id": "c6", "text": "A public directory shows less than half your own project count, so a buyer doubts every number you print." },
    { "id": "c7", "text": "Your contractor grade differs between your site and a public directory, so a panel caps the contract value." },
    { "id": "c8", "text": "A job board shows your company as a foreign entity, the kind of mismatch that stalls a background check." },
    { "id": "c9", "text": "Three different websites are given as yours, so search engines and customers build recognition on none of them." },
    { "id": "n1", "text": "A public contractor profile may carry placeholder phone details, worth checking before a panel relies on it." },
    { "id": "n2", "text": "A revenue figure on your site is not repeated anywhere outside, worth checking how it reads to a buyer." },
    { "id": "n3", "text": "One listed office carries no street address, worth checking that customers can find and reach it." },
    { "id": "n4", "text": "Several of your newest reviews carry the same date, worth watching even though it proves nothing alone." }
  ],
  "proof": {
    "id": "f1",
    "why": "The owner can check the domain's expiry in a minute, every enquiry bounces the day it lapses, and fixing it leaves every other public mismatch untouched."
  }
}

